def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    sep_rows = [r for r in range(h)
                if len(set(grid[r])) == 1 and grid[r][0] != background]
    sep_cols = [c for c in range(w)
                if len({grid[r][c] for r in range(h)}) == 1
                and grid[0][c] != background]

    def segments(length, separators):
        result, start = [], 0
        for p in separators:
            if start < p:
                result.append((start, p))
            start = p + 1
        if start < length:
            result.append((start, length))
        return result

    row_segs = segments(h, sep_rows)
    col_segs = segments(w, sep_cols)

    source = max(
        ((ri, ci) for ri in range(len(row_segs)) for ci in range(len(col_segs))),
        key=lambda item: sum(
            grid[r][c] != background
            for r in range(*row_segs[item[0]])
            for c in range(*col_segs[item[1]])
        )
    )
    r0, r1 = row_segs[source[0]]
    c0, c1 = col_segs[source[1]]
    pattern = [row[c0:c1] for row in grid[r0:r1]]

    out = [row[:] for row in grid]
    for rs, re in row_segs:
        for cs, ce in col_segs:
            for dr, r in enumerate(range(rs, re)):
                for dc, c in enumerate(range(cs, ce)):
                    out[r][c] = pattern[dr][dc]
    return out
